function checkScreenSize() {
    const screenWidth = window.innerWidth;

    if (screenWidth < 852) {
        console.log('screenWidth < 852');
        console.log(screenWidth);
        const documentsItems = document.querySelectorAll('.documents__slide');
        const documentsBtns = document.querySelectorAll('.documents-page__btns');
        if (documentsItems.length > 0 && documentsBtns.length > 0) {
            const ITEMS_TO_SHOW = 5;
            let isExpanded = false;

            // Функция для скрытия/показа отзывов
            function toggleDocuments() {
                if (isExpanded) {
                    // Скрываем элементы, начиная с 5-го
                    documentsItems.forEach((item, index) => {
                        if (index >= ITEMS_TO_SHOW) {
                            item.classList.add('hidden');
                        }
                    });
                    isExpanded = false;
                } else {
                    // Показываем все элементы
                    documentsItems.forEach(item => {
                        item.classList.remove('hidden');
                    });
                    isExpanded = true;
                }
            }

            // Инициализация - скрываем лишние элементы
            documentsItems.forEach((item, index) => {
                if (index >= ITEMS_TO_SHOW) {
                    item.classList.add('hidden');

                }

            });

            // Управляем видимостью кнопок и добавляем обработчики
            documentsBtns.forEach(btn => {
                if (documentsItems.length > ITEMS_TO_SHOW) {
                    btn.classList.remove('hidden');
                    btn.addEventListener('click', function () {
                        this.classList.add('hidden'); // Добавляем класс для нажатой кнопки
                        toggleDocuments(); // Вызываем существующую функцию
                    });
                } else {
                    btn.classList.add('hidden');
                }
            });
        }

        return true;
    } else {
        console.log('screenWidth > 852');
        console.log(screenWidth);
        return false;
    }
}

