document.addEventListener('DOMContentLoaded', function () {
    const accordionButtons = document.querySelectorAll('[data-accordion-button]');

    accordionButtons.forEach(button => {
        button.addEventListener('click', function () {
            const accordion = this.closest('.accor');
            const content = this.closest('.prices-page__accor').querySelector('.accor-full');
            const contentInner = this.closest('.prices-page__accor').querySelector('[data-accordion-content]');
            const pricesPageInfo = this.closest('.prices-page__accor').querySelector('.prices-page__info');

            // Закрываем все другие аккордеоны
            document.querySelectorAll('.accor').forEach(item => {
                if (item !== accordion) {
                    item.classList.remove('active');
                    const otherContent = item.querySelector('.accor-full');
                    const otherContentInner = item.querySelector('[data-accordion-content]');
                    const otherPricesPageInfo = item.querySelector('.prices-page__info');

                    if (otherContent) {
                        otherContent.style.maxHeight = '0px';
                    }
                    if (otherPricesPageInfo) {
                        otherPricesPageInfo.classList.remove('active');
                    }
                }
            });

            // Переключаем текущий аккордеон
            accordion.classList.toggle('active');

            if (accordion.classList.contains('active')) {
                // Открываем аккордеон
                const contentHeight = contentInner.scrollHeight;
                content.style.maxHeight = contentHeight + 'px';
                if (pricesPageInfo) {
                    pricesPageInfo.classList.add('active');
                }
            } else {
                // Закрываем аккордеон
                content.style.maxHeight = '0px';
                if (pricesPageInfo) {
                    pricesPageInfo.classList.remove('active');
                }
            }
        });
    });

    // Закрытие аккордеона при клике вне его области
    document.addEventListener('click', function (e) {
        if (!e.target.closest('.prices-page__accor')) {
            document.querySelectorAll('.accor').forEach(accordion => {
                accordion.classList.remove('active');
                const content = accordion.querySelector('.accor-full');
                const pricesPageInfo = accordion.querySelector('.prices-page__info');

                if (content) {
                    content.style.maxHeight = '0px';
                }
                if (pricesPageInfo) {
                    pricesPageInfo.classList.remove('active');
                }
            });
        }
    });
});

