function initReviews() {
    const reviewItems = document.querySelectorAll('.reviews-page__item');
    if (reviewItems !== 0) {
        function checkTextHeight() {
            const isLargeScreen = window.innerWidth > 1200;
            const maxHeight = isLargeScreen ? 360 : 150;

            reviewItems.forEach(item => {
                const textElement = item.querySelector('.reviews-page__item-text');
                const btnElement = item.querySelector('.reviews-page__item-btn');
                const btnElementSpan = item.querySelector('.reviews-page__item-span');

                const textHeight = textElement.scrollHeight;

                if (textHeight > maxHeight) {
                    textElement.classList.add('hidden');
                    textElement.style.maxHeight = maxHeight + 'px';
                    btnElement.style.display = 'flex';

                    btnElement.onclick = function () {
                        if (textElement.classList.contains('hidden')) {
                            // Раскрываем
                            textElement.style.maxHeight = textElement.scrollHeight + 'px';
                            textElement.classList.remove('hidden');
                            btnElement.classList.add('hidden');
                            btnElementSpan.innerHTML = 'Свернуть';

                            setTimeout(() => {
                                textElement.style.maxHeight = 'none';
                            }, 300);
                        } else {
                            // Скрываем
                            textElement.style.maxHeight = textElement.scrollHeight + 'px';
                            // Даем время для применения maxHeight
                            setTimeout(() => {
                                textElement.style.maxHeight = maxHeight + 'px';
                                textElement.classList.add('hidden');
                                btnElement.classList.remove('hidden');
                            }, 10);
                            btnElementSpan.innerHTML = 'Читать полностью';
                        }
                    };
                } else {
                    textElement.classList.remove('hidden');
                    textElement.style.maxHeight = 'none';
                    btnElement.style.display = 'none';
                }
            });
        }

        checkTextHeight();

        let resizeTimer;
        window.addEventListener('resize', function () {
            clearTimeout(resizeTimer);
            resizeTimer = setTimeout(checkTextHeight, 250);
        });
    }

}

document.addEventListener('DOMContentLoaded', initReviews);






